"use client";

import { useEffect, useRef } from "react";
import { buttonClass } from "@/components/ui/button";

/** html is generated by the server-side Markdown renderer with raw HTML disabled. */
export function TutorialBody({ html }: { html: string }) {
  const article = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const buttons: HTMLButtonElement[] = [];
    for (const pre of article.current?.querySelectorAll("pre") ?? []) {
      const code = pre.querySelector("code");
      if (!code) continue;
      const button = document.createElement("button");
      button.type = "button";
      button.className = buttonClass("quiet", "lesson-copy");
      button.textContent = "Copy block";
      button.setAttribute("aria-live", "polite");
      button.onclick = async () => {
        try {
          await navigator.clipboard.writeText(code.textContent ?? "");
          button.textContent = "Copied";
        } catch {
          button.textContent = "Select the text and copy manually";
        }
      };
      pre.before(button);
      buttons.push(button);
    }
    return () => { for (const button of buttons) button.remove(); };
  }, [html]);
  return <div ref={article} className="lesson-body" dangerouslySetInnerHTML={{ __html: html }} />;
}
